      "main.py": "import os\nfrom pathlib import Path\nimport tkinter as tk\nfrom tkinter import ttk\n\nroot = Path(os.environ[\"BRIDGESLLM_APP_DATA\"])\nroot.mkdir(parents=True, exist_ok=True)\nsaved = root / \"message.txt\"\nwindow = tk.Tk()\nwindow.title(\"Python Desktop Starter\")\nwindow.geometry(\"500x240\")\nframe = ttk.Frame(window, padding=24)\nframe.pack(fill=\"both\", expand=True)\nttk.Label(frame, text=\"A message that survives redeployment\").pack(anchor=\"w\")\nvalue = tk.StringVar(value=saved.read_text() if saved.exists() else \"Hello from Python\")\nentry = ttk.Entry(frame, textvariable=value, width=48)\nentry.pack(fill=\"x\", pady=16)\nstatus = tk.StringVar(value=\"Edit the message, then Save.\")\ndef save():\n    try:\n        saved.write_text(value.get()[:1000])\n        status.set(\"Saved\")\n        print(\"Message saved\", flush=True)\n    except OSError as error:\n        status.set(\"Save failed: \" + str(error))\nttk.Button(frame, text=\"Save\", command=save).pack(anchor=\"w\")\nttk.Label(frame, textvariable=status).pack(anchor=\"w\", pady=12)\nentry.focus_set()\nwindow.mainloop()\n",
