      "src/main.ts": "import { mkdir, readFile, writeFile } from 'node:fs/promises';\nimport { join } from 'node:path';\nimport { createInterface } from 'node:readline/promises';\n\nasync function main(): Promise<void> {\n  const root = process.env.BRIDGESLLM_APP_DATA;\n  if (!root) throw new Error('BRIDGESLLM_APP_DATA is missing');\n  await mkdir(root, { recursive: true });\n  const file = join(root, 'message.txt');\n  let saved = '(none)';\n  try { saved = await readFile(file, 'utf8'); }\n  catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error; }\n  console.log('Saved message: ' + saved);\n  const input = createInterface({ input: process.stdin, output: process.stdout });\n  try {\n    const value = await input.question('Write a message to save: ');\n    await writeFile(file, value.slice(0, 1000));\n    console.log('Saved. Run this app again to read your message.');\n  } finally { input.close(); }\n}\nmain().catch(error => { console.error(error); process.exitCode = 1; });\n",
