      "src/main.ts": "import { app, BrowserWindow, ipcMain } from 'electron';\nimport { mkdir, readFile, writeFile } from 'node:fs/promises';\nimport { join } from 'node:path';\nimport { pathToFileURL } from 'node:url';\n\nconst root = process.env.BRIDGESLLM_APP_DATA;\nif (!root) throw new Error('BRIDGESLLM_APP_DATA is missing');\nconst dataRoot: string = root;\napp.setPath('userData', join(dataRoot, 'electron-profile'));\napp.disableHardwareAcceleration();\nconst documentUrl = pathToFileURL(join(__dirname, '../ui/index.html')).href;\napp.whenReady().then(async () => {\n  await mkdir(dataRoot, { recursive: true });\n  const file = join(dataRoot, 'message.txt');\n  const window = new BrowserWindow({ width: 540, height: 320,\n    webPreferences: { preload: join(__dirname, 'preload.js'), sandbox: true,\n      contextIsolation: true, nodeIntegration: false, webSecurity: true } });\n  const trusted = (event: Electron.IpcMainInvokeEvent): void => {\n    if (event.sender !== window.webContents || event.senderFrame !== window.webContents.mainFrame\n      || event.senderFrame.url !== documentUrl) throw new Error('Untrusted caller');\n  };\n  ipcMain.handle('message:read', async event => {\n    trusted(event);\n    try { return await readFile(file, 'utf8'); }\n    catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') return 'Hello from TypeScript'; throw error; }\n  });\n  ipcMain.handle('message:save', async (event, value: unknown) => {\n    trusted(event);\n    if (typeof value !== 'string' || value.length > 1000) throw new Error('Message must be at most 1000 characters');\n    await writeFile(file, value);\n    console.log('Message saved');\n  });\n  window.webContents.setWindowOpenHandler(() => ({ action: 'deny' }));\n  window.webContents.on('will-navigate', event => event.preventDefault());\n  window.webContents.session.setPermissionRequestHandler((_contents, _permission, callback) => callback(false));\n  await window.loadURL(documentUrl);\n}).catch(error => { console.error(error); app.exit(1); });\napp.on('window-all-closed', () => app.quit());\n",
      "src/preload.ts": "import { contextBridge, ipcRenderer } from 'electron';\ncontextBridge.exposeInMainWorld('messages', {\n  read: (): Promise<string> => ipcRenderer.invoke('message:read'),\n  save: (value: string): Promise<void> => ipcRenderer.invoke('message:save', value),\n});\n",
      "src/renderer.ts": "interface Window { messages: { read(): Promise<string>; save(value: string): Promise<void> } }\nconst input = document.querySelector<HTMLInputElement>('#message')!;\nconst statusText = document.querySelector<HTMLElement>('#status')!;\nconst save = document.querySelector<HTMLButtonElement>('#save')!;\nwindow.messages.read().then(value => { input.value = value; input.focus(); })\n  .catch(error => { statusText.textContent = 'Read failed: ' + String(error); });\nsave.addEventListener('click', () => {\n  save.disabled = true;\n  window.messages.save(input.value).then(() => { statusText.textContent = 'Saved'; })\n    .catch(error => { statusText.textContent = 'Save failed: ' + String(error); })\n    .finally(() => { save.disabled = false; });\n});\n",
      "ui/index.html": "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><title>TypeScript Desktop Starter</title>\n<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; script-src 'self'; style-src 'self'; base-uri 'none'; form-action 'none'; connect-src 'none'\">\n<link rel=\"stylesheet\" href=\"style.css\"></head><body>\n<h1>TypeScript Desktop Starter</h1><label for=\"message\">A message that survives redeployment</label>\n<input id=\"message\" maxlength=\"1000\"><button id=\"save\">Save</button><p id=\"status\" role=\"status\">Edit the message, then Save.</p>\n<script src=\"../dist/renderer.js\"></script></body></html>\n",
